pm.test("Durum kodu 200 olmali", function () {
    pm.response.to.have.status(200);
});

pm.test("Yanit 10 kullanici iceren bir liste olmali", function () {
    const kullanicilar = pm.response.json();

    pm.expect(kullanicilar).to.be.an("array");
    pm.expect(kullanicilar).to.have.lengthOf(10);
});

pm.test("Kullanici alanlari ve veri tipleri dogru olmali", function () {
    const kullanicilar = pm.response.json();
    pm.expect(kullanicilar).to.be.an("array").that.is.not.empty;

    kullanicilar.forEach(function (kullanici) {
        pm.expect(kullanici.id).to.be.a("number");
        pm.expect(kullanici.name).to.be.a("string").and.not.empty;
        pm.expect(kullanici.username).to.be.a("string").and.not.empty;
        pm.expect(kullanici.email).to.be.a("string").and.not.empty;
    });
});

pm.test("Kullanici ID degerleri benzersiz olmali", function () {
    const kullanicilar = pm.response.json();
    pm.expect(kullanicilar).to.be.an("array").that.is.not.empty;

    const idler = kullanicilar.map(function (kullanici) {
        return kullanici.id;
    });

    pm.expect(new Set(idler).size).to.eql(idler.length);
});

